package com.sudodaniel.ownchatcolor;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("ownchatcolor")
public interface OwnChatColorConfig extends Config
{
	@ConfigItem(
		keyName = "color",
		name = "Color",
		description = "Color of your own messages in clan and group ironman chat"
	)
	default Color color()
	{
		return new Color(0x00A0FF);
	}
}

package com.sudodaniel.ownchatcolor;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Own Chat Color",
	description = "Recolors your own messages in clan and group ironman chat",
	tags = {"clan", "group", "ironman", "gim", "chat", "color", "colour"}
)
public class OwnChatColorPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private OwnChatColorConfig config;

	@Provides
	OwnChatColorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OwnChatColorConfig.class);
	}

	// Runs after other plugins, so tags they add (e.g. highlights) are already in the message
	@Subscribe(priority = -2)
	public void onChatMessage(ChatMessage event)
	{
		switch (event.getType())
		{
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
				break;
			default:
				return;
		}

		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null || event.getName() == null
			||!Text.standardize(event.getName()).equals(Text.standardize(local.getName())))
		{
			return;
		}

		Color color = config.color();
		MessageNode node = event.getMessageNode();
		// A </col> inside the message would reset to the default color, so point it back to ours
		String message = node.getValue().replace(ColorUtil.CLOSING_COLOR_TAG, ColorUtil.colorTag(color));
		node.setValue(ColorUtil.wrapWithColorTag(message, color));
	}
}

package com.sudodaniel.ownchatcolor;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class OwnChatColorPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OwnChatColorPlugin.class);
		RuneLite.main(args);
	}
}
